def effective(defaults, sampler):
    # Your code here
    return {}

coding.solution:
def effective(defaults, sampler):
    out = dict(defaults)
    for k, v in sampler.items():
        if v not in (None, ''):
            out[k] = v
    return out

tests.code:
d = {'server':'x'}
r = effective(d, {'server':'y'})
assert d == {'server':'x'} and r == {'server':'y'}, r

