def merge_headers(managers):
    # Your code here
    return None

coding.solution:
def merge_headers(managers):
    merged = {}
    for manager in managers:
        for name, value in manager:
            merged[name.lower()] = (name, value)
    return {name: value for name, value in merged.values()}
